export const FEATURES={assessment:'Avaliações individuais',live:'Quiz ao vivo',multiple:'Múltiplas respostas',blanks:'Preencher lacunas',code:'Questões com código',import:'Importação JSON',tracking:'Acompanhamento dos alunos',trackingTeam:'Equipe de acompanhamento',warnings:'Emissão de advertências verbais e escritas',questionBank:'Banco de questões'};
export const DEFAULT_PLANS=[{id:'free',name:'Free',active:true,price:0,currency:'BRL',period:'monthly',limits:{students:50,responses:50,assessmentQuestions:20,quizQuestions:20},features:Object.fromEntries(Object.keys(FEATURES).map(k=>[k,!['trackingTeam','warnings'].includes(k)]))},{id:'premium',name:'Premium',active:true,price:0,currency:'BRL',period:'monthly',limits:{students:null,responses:null,assessmentQuestions:null,quizQuestions:null},features:Object.fromEntries(Object.keys(FEATURES).map(k=>[k,true]))},{id:'custom',name:'Personalizado',active:true,price:0,currency:'BRL',period:'negotiated',limits:{students:100,responses:100,assessmentQuestions:50,quizQuestions:50},features:Object.fromEntries(Object.keys(FEATURES).map(k=>[k,true]))}];
export function validPlan(p){return !!p&&typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=80&&typeof p.active==='boolean'&&Number.isFinite(p.price)&&p.price>=0&&p.price<=1000000&&p.currency==='BRL'&&['monthly','yearly','one_time','negotiated'].includes(p.period)&&p.limits&&Object.keys(DEFAULT_PLANS[0].limits).every(k=>p.limits[k]===null||Number.isSafeInteger(p.limits[k])&&p.limits[k]>=0&&p.limits[k]<=100000)&&p.features&&Object.keys(FEATURES).every(k=>typeof p.features[k]==='boolean')&&(!p.features.trackingTeam&&!p.features.warnings||p.features.tracking);}
export function capacity(limit,used,existing=false){return existing||limit===null||used<limit;}
export function examPlanIssue(plan,e){if(!plan.active)return'Plano indisponível. Solicite ajuste ao administrador.';const mode=e.mode==='live'?'live':'assessment';if(!plan.features[mode])return'Recurso indisponível no seu plano.';const limit=plan.limits[mode==='live'?'quizQuestions':'assessmentQuestions'];if(limit!==null&&e.questions.length>limit)return`Seu plano permite até ${limit} perguntas nesta atividade.`;for(const q of e.questions){if(['multiple','blanks'].includes(q.type)&&!plan.features[q.type])return'Tipo de questão indisponível no plano.';if((q.code||q.responseFormat==='code')&&!plan.features.code)return'Questões com código não estão liberadas no plano.';}return null;}

export function normalizePlan(p){return{...p,features:{tracking:false,trackingTeam:false,warnings:false,questionBank:false,...p.features}};}
